card.content:
{
  "conclusion": "周末两天（9月8-9日）天气良好，云量低，适合拍摄星空或夜景；建议选择默认机位（上海），在9月8日或9日夜间前往，携带广角镜头和三脚架，利用新月无月光干扰拍摄银河。",
  "evidence": [
    {
      "tool": "weather_forecast",
      "field": "每日预报",
      "confidence": "high",
      "note": "9月8日云量30%，9月9日18%，天气晴朗，适合拍摄。"
    },
    {
      "tool": "moon_phase",
      "field": "月相名称",
      "confidence": "high",
      "note": "新月，月光影响低，利于星空摄影。"
    },
    {
      "tool": "sun_times",
      "field": "日落",
      "confidence": "high",
      "note": "日落时间18:06，之后可进入蓝调时段和夜间拍摄。"
    }
  ],
  "confidence": "high",
  "time_window": "9月8日或9日 18:30 - 次日05:00",
  "locations": [
    {
      "name": "默认机位（上海）",
      "reason": "天气晴朗，云量低，且无月光干扰，适合星空拍摄。"
    }
  ],
  "params": [
    {
      "name": "ISO",
      "value": "3200",
      "reason": "高ISO以捕捉暗弱星光，配合新月低光环境。"
    },
    {
      "name": "光圈",
      "value": "f/2.8",
      "reason": "大光圈增加进光量，适合星空摄影。"
    },
    {
      "name": "快门",
      "value": "15s",
      "reason": "根据500法则，避免星轨，同时保证曝光充足。"
    }
  ],
  "alternatives": [
    "若9月8日天气有变，可改期至9月9日，云量更低。",
    "若追求城市夜景，可在日落前后拍摄蓝调时段，但星空条件更佳。"
  ],
  "degraded": ""
}
